'use strict';
let data=null,view='overview',platform='all',pausedOnly=false,query='',notesQuery='',tradeFilter='all',refreshing=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=4)=>v===undefined||v===null||v===''?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
const date=s=>s?new Date(String(s).replace(' ','T')+(/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(String(s).replace(' ','T'))?':00+08:00':'')):null;
const stamp=s=>{let d=date(s);return d&&!isNaN(d)?d.toLocaleString('zh-TW',{timeZone:'Asia/Singapore',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'未有新資料';};
function age(s){let d=date(s);if(!d||isNaN(d))return '尚無讀取時間';let m=Math.max(0,Math.floor((Date.now()-d)/60000));return m<1?'剛剛更新':m<60?`${m} 分鐘前更新`:m<1440?`${Math.floor(m/60)} 小時前更新`:`${Math.floor(m/1440)} 天前更新`;}
function initials(n){if(n.includes('24WD'))return '24';if(/rebirth/i.test(n))return 'JS';if(/Jingxin/.test(n))return '靜';if(/Callme/.test(n))return 'LB';return n.slice(0,2);}
function hasStale(t){let d=date(t.lastCheckAt);return !d||Date.now()-d>(t.platform==='OKX'?180000:600000);}
function status(t){if(t.positionMode==='closed')return ['實盤已關閉','paused'];if(t.positionMode==='hidden'&&!t.liveEnabled)return ['持倉未公開','paused'];if(t.positionsEnabled)return ((t.continuousPositions||t.liveStatus==='healthy')&&!hasStale(t))?['實盤監控中','healthy']:['實盤資料延遲','stale'];if(t.liveEnabled){if(hasStale(t))return ['巡檢資料延遲','stale'];if(t.liveStatus==='live')return ['正在直播','live'];return t.liveStatus==='healthy'?['直播監控中','healthy']:['巡檢待恢復','stale'];}return t.positionMode==='blocked'?['倉位通道待接通','stale']:['倉位已暫停','paused'];}
function snippet(s){return (s.summary||'逐字稿已保存，摘要尚未完成。').replace(/https?:\/\/\S+/g,'').split('\n').filter(x=>x.trim()&&!/^(靜星|rebirth|場次|時間|直播連結|回放：)/.test(x)).join(' ').slice(0,230);}
function badge(s,c=''){return `<span class="badge ${c}">${esc(s)}</span>`;}
function render(){if(!data)return;$('#navcount').textContent=data.traders.length;$('#today').textContent=new Date().toLocaleDateString('zh-TW',{timeZone:'Asia/Singapore',year:'numeric',month:'long',day:'numeric',weekday:'short'});$('#updated').textContent='資料彙整 '+stamp(data.generatedAt);$('#follow-count').textContent=`${data.traders.length} 位`;let snapshot=!['local','remote-live'].includes(data.dataMode);$('#connection').textContent=snapshot?'雲端快照':data.dataMode==='remote-live'?'加密監控資料已連線':'本機資料已連線';$('#connection').classList.toggle('warning',snapshot);$('#snapshot-banner').classList.toggle('hidden',!snapshot);$('#snapshot-banner').textContent=`目前顯示 ${stamp(data.generatedAt)} 的私密快照，不會假稱即時更新。在執行監控的 Mac 開啟 http://127.0.0.1:8792/ 可看自動更新的資料。`;renderStats();renderTraders();renderLatest();renderPipeline();window.positionDesk.update(data);renderNotes();renderTrades();}
function renderStats(){let active=data.traders.filter(t=>t.liveEnabled).length,paused=data.traders.filter(t=>t.positionMode==='paused').length,live=data.traders.filter(t=>t.liveStatus==='live'&&!hasStale(t)).length;let a=[['關注交易員',data.traders.length,'跨平台集中管理','◈'],['直播監控',active,live?`${live} 位正在直播`:'每 2 分鐘巡檢','◉'],['公開實盤',data.traders.filter(t=>t.positionsEnabled).length,'OKX 30 秒 · 幣安 60 秒','⇄'],['倉位待接通',data.traders.filter(t=>t.positionMode==='blocked').length,data.services.binancePositions?'已接通獨立內置瀏覽器':'檢查登入與採集狀態','Ⅱ']];$('#stats').innerHTML=a.map(([label,n,sub,icon])=>`<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${n.toString().padStart(2,'0')}</div><small>${esc(sub)}</small></div>`).join('');}
function renderTraders(){let ts=data.traders.filter(t=>(platform==='all'||t.platform===platform)&&(!pausedOnly||t.positionMode==='paused')&&t.name.toLowerCase().includes(query.toLowerCase()));$('#trader-list').innerHTML=ts.length?ts.map(t=>{let [label,cls]=status(t);return `<div class="trader-row" role="button" tabindex="0" data-trader="${esc(t.id)}"><span class="avatar ${t.platform==='OKX'?'okx':!t.liveEnabled?'yellow':''}">${initials(t.name)}</span><div class="person"><strong>${esc(t.name)}</strong><small><span class="platform-label ${t.platform.toLowerCase()}">${t.platform.toUpperCase()}</span><span>·</span><span>${t.positionsEnabled?'公開成交與資產':t.liveEnabled?'直播 / 逐字稿 / 摘要':'歷史倉位記錄'}</span></small></div><div class="person-side">${badge(label,cls)}<small>${t.platform==='OKX'?'總敞口≈'+fmt(t.overallExposureLeverage,2)+'x · '+age(t.lastCheckAt):t.positionMode==='paused'&&t.liveEnabled?'倉位已暫停 · '+age(t.lastCheckAt):t.liveEnabled||t.positionsEnabled?age(t.lastCheckAt):t.positionMode==='blocked'?'採集待恢復':t.positionMode==='closed'?'交易員已關閉實盤':t.positionMode==='hidden'?'交易員未公開持倉':'依指示暫停'}</small></div><span class="row-arrow">›</span></div>`;}).join(''):'<div class="empty">沒有符合的關注對象</div>';$('#paused-filter').textContent=pausedOnly?'顯示全部':'查看已暫停';$('#paused-filter').classList.toggle('active',pausedOnly);}
function renderLatest(){let s=data.sessions.find(s=>s.summaryKind==='reviewed'&&s.summary)||data.sessions.find(s=>s.summary);$('#latest-note').innerHTML=s?`<div class="noteauthor">${esc(s.creator)} · ${stamp(s.at)}</div><h3>${esc(s.title)}</h3>${badge(s.summaryKind==='excerpt'?'原文摘錄':'已整理摘要',s.summaryKind==='excerpt'?'paused':'healthy')}<div class="note-preview">${esc(snippet(s))}</div><button class="read-note" data-session="${esc(s.id)}">閱讀筆記 <span>↗</span></button>`:'<h3>等候下一場直播</h3><p>有可讀內容後會在這裡顯示。</p>';}
function renderPipeline(){let checks=[['幣安直播巡檢',data.services.live,data.traders.filter(t=>t.liveEnabled).every(t=>!hasStale(t))],...data.traders.filter(t=>t.platform==='OKX').map(t=>['OKX '+t.name,data.services[t.serviceKey],!hasStale(t)]),['幣安公開帳戶巡檢',data.services.binancePublic,data.services.binancePublic],['幣安倉位收集',data.services.binancePositions,data.services.binancePositions]];$('#pipeline').innerHTML=checks.map(([n,on,recent],i)=>`<div class="pipeline-row"><span>${n}</span>${badge(on&&recent?'正在運行':i===checks.length-1?'採集待恢復':'資料延遲',on&&recent?'healthy':'stale')}</div>`).join('');}
function renderHoldings(){$('#holdings').innerHTML=data.traders.filter(t=>t.platform==='OKX').map(t=>{let freshSnapshot=Date.now()-(date(t.snapshotAt)||0)<900000;return `<div class="sectionline"><h2>${esc(t.name)} 最新公開資產</h2><div><a class="textbutton" style="margin-right:16px" href="${esc(t.orbitUrl)}" target="_blank" rel="noopener">OKX 星球 ↗</a><a class="textbutton" href="${esc(t.profileUrl)}" target="_blank" rel="noopener">公開實盤 ↗</a></div></div><div class="holdings-card"><div class="holdings-top"><span class="small muted">合約倉位 ${t.positions.length} 筆 · 現貨資產 ${t.assets.length} 類</span><div class="small muted">快照 ${stamp(t.snapshotAt)} ${freshSnapshot?'':'· 非即時'}</div></div><div class="leverage-strip"><div><small>槓桿（公開持倉占比）</small><strong>約 ${fmt(t.spotExposureLeverage,2)}x</strong></div><div><small>合約多頭槓桿</small><strong>${fmt(t.contractLongLeverage,2)}x</strong></div><div><small>合約空頭槓桿</small><strong>${fmt(t.contractShortLeverage,2)}x</strong></div></div><p class="small muted" style="margin-top:10px">槓桿按公開資產占比加總：BTC 占比 ${fmt(Number((t.assets.find(a=>a.currency==='BTC')||{}).percent||0)*100,2)}%，合計約 ${fmt(t.spotExposureLeverage,2)} 倍。合約多空目前 ${fmt(t.contractLongLeverage,2)}x / ${fmt(t.contractShortLeverage,2)}x。歷史成交單上的設定倍數不拿來冒充現在的槓桿。</p>${t.positions.length?'<h3 style="margin-top:20px">目前公開合約持倉</h3>'+t.positions.map(p=>positionCard({symbol:p.instId,direction:p.posSide==='short'||Number(p.pos)<0?'SHORT':'LONG',quantity:Math.abs(Number(p.pos)),quantityUnit:['SWAP','FUTURES'].includes(p.instType)?'張':p.posCcy,leverage:p.lever,entryPrice:p.avgPx,markPrice:p.markPx,unrealizedPnl:p.upl,pnlUnit:p.marginCcy||p.quoteCcy,margin:p.margin,marginUnit:p.marginCcy,liquidationPrice:p.liqPx||null})).join(''):''}<div class="holdings-assets">${t.assets.length?t.assets.map(a=>`<div class="asset"><strong>${esc(a.currency)}</strong><div>${fmt(a.amount,6)}</div><small>公開持有量 · 占比 ${fmt(Number(a.percent)*100,2)}% · 約 ${fmt(a.percent,2)}x</small></div>`).join(''):'<div class="muted small">尚無可用公開資產快照。</div>'}</div></div>`;}).join('');}
function renderNotes(){let ss=data.sessions.filter(s=>(s.creator+' '+s.title).toLowerCase().includes(notesQuery.toLowerCase()));$('#notes-count').textContent=`${ss.length} 場`;$('#notes-grid').innerHTML=ss.length?ss.map(s=>`<article class="note-card"><div class="small muted">${esc(s.creator)} <span style="float:right">${stamp(s.at)}</span></div><h3>${esc(s.title)}</h3><div>${badge(s.summary?s.summaryKind==='excerpt'?'原文摘錄':s.summaryKind==='reviewed'?'人工整理':'摘要已保存':'摘要待完成',s.summaryKind==='excerpt'?'paused':s.summary?'healthy':'neutral')} ${s.hasTranscript?badge('逐字稿','neutral'):''}</div><div class="note-preview">${esc(snippet(s))}</div><div class="note-bottom"><small>${s.durationSeconds?Math.floor(s.durationSeconds/60)+' 分鐘':'本機存檔'} · ${esc(s.stage)}</small><button data-session="${esc(s.id)}">打開筆記 ↗</button></div></article>`).join(''):'<div class="empty">沒有符合的直播筆記</div>';}
function filteredTrades(){return data.events.filter(e=>tradeFilter==='all'||e.traderId===tradeFilter);}
function renderTrades(){let rows=filteredTrades(),ts=data.traders.filter(t=>t.platform==='OKX'&&(tradeFilter==='all'||t.id===tradeFilter));$('#trades-summary').textContent=`${ts.map(t=>t.name).join(' + ')} · 共收錄 ${ts.reduce((n,t)=>n+(t.totalTrades||0),0)} 筆 · 顯示 ${rows.length} 筆 · 每30秒讀取本機資料`;
$('#trades-body').innerHTML=rows.map(e=>`<tr><td>${stamp(e.at)}</td><td>${esc(e.creator)}</td><td>${badge(e.action,/買|開多|加多|減空/.test(e.action)?'healthy':'paused')}</td><td>${esc(e.instrument)}</td><td>${fmt(e.size,8)} ${esc(e.unit)}</td><td>${e.configuredLeverage?fmt(e.configuredLeverage,2)+'x':'—'}</td><td title="${esc(e.priceKind)}">${fmt(e.price,4)}${e.priceKind==='委託價'?' *':''}</td></tr>`).join('');}
function readSession(id,mode='summary'){let s=data.sessions.find(s=>s.id===id);if(!s)return;$('#reader-label').textContent=`${s.creator} · ${mode==='transcript'?'帶時間逐字稿':s.summaryKind==='excerpt'?'原文摘錄備援':'直播筆記'}`;$('#reader-title').textContent=s.title;$('#reader-meta').textContent=`${stamp(s.at)} · 場次 ${s.id} · ${mode==='transcript'?'語音辨識稿，數字與說話人需核對':s.summaryKind==='excerpt'?'摘要服務降級，此處為原文摘錄，非完整語意摘要。':'依保存內容展示，歷史觀點不代表現在持倉。'}`;$('#reader-actions').innerHTML=`<button data-reader-mode="summary" data-id="${esc(id)}">摘要 / 摘錄</button>${s.transcript?`<button data-reader-mode="transcript" data-id="${esc(id)}">逐字稿</button>`:''}<button data-download="${esc(id)}" data-mode="${mode}">下載文字檔</button><a href="${esc(s.url)}" target="_blank" rel="noopener">幣安原場次 ↗</a>`;$('#reader-body').textContent=(mode==='transcript'?s.transcript:s.summary)||'這場內容尚未完成整理。';$('#reader-body').scrollTop=0;if(!$('#reader').open)$('#reader').showModal();}
function readTrader(id){let t=data.traders.find(t=>t.id===id);if(!t)return;$('#reader-label').textContent=t.platform+' · 關注檔案';$('#reader-title').textContent=t.name;$('#reader-meta').textContent=t.lastCheckAt?'最後成功巡檢 '+stamp(t.lastCheckAt):'倉位監控已按指示暫停，舊資料不作當前持倉。';$('#reader-actions').innerHTML=`${t.positionPermission||t.platform==='OKX'?`<button data-open-positions="${esc(t.id)}">查看持倉詳情</button>`:''}<a href="${esc(t.profileUrl)}" target="_blank" rel="noopener">平台原頁 ↗</a>${t.smartMoneyUrl?`<a href="${esc(t.smartMoneyUrl)}" target="_blank" rel="noopener">聰明錢檔案 ↗</a>`:''}${t.orbitUrl?`<a href="${esc(t.orbitUrl)}" target="_blank" rel="noopener">OKX 星球 ↗</a><button id="go-trades">查看成交記錄</button>`:''}`;let sessions=data.sessions.filter(s=>s.traderId===id);$('#reader-body').innerHTML=`<div class="profile-facts"><div class="fact"><span>目前狀態</span>${badge(...status(t))}</div>${t.platform==='OKX'?`<div class="fact"><span>槓桿 / 公開占比換算</span><div>約 ${fmt(t.spotExposureLeverage,2)}x</div></div><div class="fact"><span>合約多頭 / 空頭槓桿</span><div>${fmt(t.contractLongLeverage,2)}x / ${fmt(t.contractShortLeverage,2)}x</div></div>`:''}<div class="fact"><span>倉位收集</span><div>${esc(t.positionNote||(t.positionsEnabled?'已啟用，公開資料收集':'未加入'))}</div></div><div class="fact"><span>直播監控</span><div>${t.liveEnabled?'每 '+t.pollSeconds+' 秒巡檢':'未加入'}</div></div>${t.historicalEventCount?`<div class="fact"><span>歷史倉位事件</span><div>${t.historicalEventCount} 筆（歷史存檔）</div></div>`:''}<h3 style="margin-top:24px">直播存檔 · ${sessions.length} 場</h3>${sessions.length?sessions.map(s=>`<button class="sessionlink" data-session="${esc(s.id)}">${esc(s.title)} <span class="small muted" style="float:right">${stamp(s.at)} ↗</span></button>`).join(''):'<div class="muted small">此關注對象尚無本機直播存檔。</div>'}</div>`;if(!$('#reader').open)$('#reader').showModal();}
function setView(v){view=v;$$('.view').forEach(x=>x.classList.toggle('hidden',x.id!==v+'-view'));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#crumb').textContent={overview:'總覽',notes:'直播筆記',trades:'成交記錄'}[v];$('#page-title').innerHTML={overview:'實盤觀察台<span class="livepill">幣安 × OKX</span>',notes:'每一場，都有跡可循。',trades:'公開操作，逐筆留存。'}[v];$('#subtitle').textContent={overview:'先看持倉與風險，再看交易員的直播和研究。',notes:'摘要、原文摘錄與逐字稿，在這裡集中閱讀。',trades:'24WD 與十老板的公開成交，按時間集中閱讀。'}[v];window.scrollTo({top:0,behavior:'smooth'});}
function download(name,text,mime='text/plain;charset=utf-8'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCsv(){let keys=['at','creator','action','instrument','size','unit','price','priceKind','configuredLeverage','orderId'];let rows=[keys,...filteredTrades().map(e=>keys.map(k=>e[k]??''))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','));download('OKX-public-trades.csv','\uFEFF'+rows.join('\r\n'),'text/csv;charset=utf-8');}
async function fetchData(path,timeout=15000){let r=await fetch(path,{signal:AbortSignal.timeout(timeout),cache:'no-store'});if(!r.ok)throw Error(r.status);let d=await r.json();if(!Array.isArray(d.traders))throw Error('schema');return d;}

const LIVE_GIST={"gistId":"18c54678e6133e7891481cab9fb60912","rawUrl":"https://gist.githubusercontent.com/jack0752168/18c54678e6133e7891481cab9fb60912/raw/smart-money.enc.json"};

function keyBytes(){let k=new URLSearchParams(location.hash.slice(1)).get('k');if(!k)throw Error('請使用帳戶匯總入口或私人書籤');k=k.replace(/-/g,'+').replace(/_/g,'/');while(k.length%4)k+='=';return Uint8Array.from(atob(k),c=>c.charCodeAt(0));}
async function loadEncrypted(){const ck=await crypto.subtle.importKey('raw',keyBytes(),'AES-GCM',false,['decrypt']);let env;try{const r=await fetch(LIVE_GIST.rawUrl+'?t='+Math.floor(Date.now()/60000),{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('snapshot '+r.status);env=await r.json();if(env.chunks){const parts=await Promise.all(env.chunks.map(async name=>{const cr=await fetch(LIVE_GIST.rawUrl.replace('smart-money.enc.json',name)+'?t='+Math.floor(Date.now()/60000),{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!cr.ok)throw Error('chunk '+cr.status);return (await cr.json()).data;}));env={encoding:'gzip',data:parts.join('')};}try{sessionStorage.setItem('smart-cipher',JSON.stringify(env));}catch(ignore){}}catch(e){const cached=sessionStorage.getItem('smart-cipher');if(!cached)throw e;env=JSON.parse(cached);}const bytes=Uint8Array.from(atob(env.data),c=>c.charCodeAt(0));const compressed=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.slice(0,12)},ck,bytes.slice(12));const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));const d=JSON.parse(await new Response(stream).text());if(!Array.isArray(d.traders))throw Error('schema');return d;}

async function refresh(manual=false){if(refreshing)return;refreshing=true;$('#refresh').style.opacity='.4';try{if(location.hostname==='127.0.0.1'||location.hostname==='localhost'){data=await fetchData('/api/dashboard');}else{data=await loadEncrypted();}render();if(manual)toast('已重新讀取'+(data.dataMode==='local'?'本機資料':'加密監控資料'));}catch(e){$('#connection').textContent='資料連線中斷';$('#connection').classList.add('warning');if(!data)$('#trader-list').innerHTML='<div class="empty">暫時無法讀取資料，請重新整理。</div>';if(manual)toast('連線暫時中斷，已保留上一份畫面');}finally{refreshing=false;$('#refresh').style.opacity='1';}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3500);}
document.addEventListener('click',e=>{let b=e.target.closest('[data-view],[data-platform],[data-trader],[data-session],[data-reader-mode],[data-download]');if(b){if(b.dataset.view)setView(b.dataset.view);if(b.dataset.platform){platform=b.dataset.platform;$$('[data-platform]').forEach(x=>x.classList.toggle('selected',x===b));renderTraders();}if(b.dataset.trader)readTrader(b.dataset.trader);if(b.dataset.session)readSession(b.dataset.session);if(b.dataset.readerMode)readSession(b.dataset.id,b.dataset.readerMode);if(b.dataset.download){let s=data.sessions.find(x=>x.id===b.dataset.download);let mode=b.dataset.mode;download(`${s.creator}-${s.id}-${mode}.txt`,`${s.creator} · ${s.title}\n來源 ${s.url}\n\n${mode==='transcript'?s.transcript:s.summary}`);}}if(e.target.id==='go-trades'){$('#reader').close();setView('trades');}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-trader]'))readTrader(e.target.dataset.trader);});$('#search').addEventListener('input',e=>{query=e.target.value;renderTraders();});$('#notes-search').addEventListener('input',e=>{notesQuery=e.target.value;renderNotes();});$('#paused-filter').onclick=()=>{pausedOnly=!pausedOnly;renderTraders();};$('#close-reader').onclick=()=>$('#reader').close();$('#reader').addEventListener('click',e=>{if(e.target===$('#reader')){let r=$('#reader').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#reader').close();}});$('#trade-filter').onchange=e=>{tradeFilter=e.target.value;renderTrades();};$('#export-csv').onclick=exportCsv;$('#refresh').onclick=()=>refresh(true);refresh();setInterval(()=>{if(!document.hidden)refresh();},30000);

function accountBadges(p){if(p?.stale)return badge('公開狀態已過期','stale');if(!p||p.accountOpen==null)return badge('公開狀態待核對','neutral');if(p.accountOpen===false)return badge('實盤已關閉','paused');let open=badge('實盤已打開','healthy');if(p.positionVisibility==='public')return open+badge('持倉公開','healthy');if(p.positionVisibility==='hidden')return open+badge('當前倉位不公開','neutral');return open;}
function positionCard(x){let book=x.market==='CM'?'币本位':x.market==='UM'?'U本位':'';let side=x.direction==='SHORT'?'空':'多';let qtyDigits=x.quantityUnit==='张'?0:4;let pxDigits=x.market==='CM'?1:5;return '<div class="position-grid"><div><small>標的 / 方向</small><strong>'+esc(book)+' '+esc(x.symbol)+' · '+side+' '+esc(x.contractType||'')+' '+esc(x.marginMode||'')+'</strong></div><div><small>數量 / 槓桿</small><strong>'+fmt(x.quantity, qtyDigits)+' '+esc(x.quantityUnit)+' · '+fmt(x.leverage,0)+'x</strong></div><div><small>開倉價 / 標記價</small><strong>'+fmt(x.entryPrice, pxDigits)+' / '+fmt(x.markPrice, pxDigits)+'</strong></div><div><small>未實現損益</small><strong>'+fmt(x.unrealizedPnl, x.pnlUnit==='BTC'?4:2)+' '+esc(x.pnlUnit||'USDT')+(x.roi!=null?' · '+fmt(x.roi*100,2)+'%':'')+'</strong></div><div><small>保證金</small><strong>'+fmt(x.margin, x.marginUnit==='BTC'?4:2)+' '+esc(x.marginUnit||'USDT')+'</strong></div><div><small>強平價</small><strong>'+fmt(x.liquidationPrice,1)+'</strong></div></div>';}
function renderBinancePositions(){let ts=data.traders.filter(t=>t.positionPermission);let rows=ts.map(t=>{let p=t.positionPermission||{};let facts=[];if(p.smartMoneyId){facts.push('聰明錢 '+(p.accountName||''));facts.push('U本位保證金資產 '+fmt(p.umMarginBalance,2)+' USD');facts.push('币本位保證金資產 '+fmt(p.cmMarginBalance,2)+' USD');}if(p.currentCopyCount!=null){facts.push('帶單跟單 '+p.currentCopyCount+' 人');facts.push('帶單保證金 '+fmt(p.marginBalance,2)+' USDT');}if(p.roi7d!=null)facts.push('帶單近 7 日 '+fmt(p.roi7d,2)+'%');if(p.accountName&&!p.smartMoneyId)facts.push('帳號 '+p.accountName);let counts=t.marketCounts?'<div class="small" style="margin-top:8px">U本位 '+(t.marketCounts.UM??0)+' 筆 · 币本位 '+(t.marketCounts.CM??0)+' 筆</div>':'';let positions=(t.observedPositions&&t.observedPositions.length)?t.observedPositions.map(positionCard).join('')+(t.positionReadNote?'<div class="small muted">'+esc(t.positionReadNote)+'</div>':'')+'<div class="small muted">讀取 '+stamp(t.positionsCapturedAt)+' · '+esc(t.positionsSource||'頁面讀數')+(t.continuousPositions?' · 每60秒連續採集。</div>':' · 非連續倉位。</div>'):(p.positionVisibility==='hidden'?'<div class="small muted" style="margin-top:8px">實盤開著，當前倉位被設成不公開。公開持倉接口回空，這裡不補造倉位。</div>':'<div class="small muted" style="margin-top:8px">沒有可展示的當前倉位。</div>');let orders=(t.publicOrders&&t.publicOrders.length)?'<div class="small" style="margin-top:8px">帶單最近公開成交（U本位帶單，不是聰明錢倉位）</div>'+t.publicOrders.map(o=>'<div class="small muted">'+stamp(o.at)+' · '+esc(o.symbol)+' '+esc(o.side)+' '+fmt(o.quantity,4)+' '+esc(o.quantityUnit||'')+' · 均價 '+fmt(o.price,2)+(o.pnl?' · 該筆盈虧 '+fmt(o.pnl,2):'')+'</div>').join(''):'';return '<div class="binance-position-row"><div class="holdings-top"><strong><a href="'+esc(t.smartMoneyUrl||t.profileUrl)+'" target="_blank" rel="noopener">'+esc(t.name)+' ↗</a></strong><div>'+accountBadges(p)+' '+badge(t.positionMode==='blocked'?'倉位通道待接通':t.positionMode==='paused'?'連續收集暫停':'只讀公開接口','paused')+'</div></div><div class="small muted" style="margin-top:6px">'+esc(facts.filter(Boolean).join(' · ')||'無額外公開帳戶數字')+' · 核對 '+stamp(p.checkedAt)+'</div>'+counts+positions+orders+'</div>';}).join('');$('#binance-positions').innerHTML='<div class="sectionline"><h2>幣安廣場 / 帶單實盤 <span>'+ts.length+' 位 · 公開狀態每 90 秒核對</span></h2>'+badge(data.services.binancePositions?'獨立內置瀏覽器採集中':'倉位採集待恢復',data.services.binancePositions?'healthy':'stale')+'</div><div class="holdings-card"><p class="small muted" style="margin-bottom:15px">帳號開或關看幣安公開狀態。電魚哥要看聰明錢檔案：U本位和币本位是分開的。倉位不公開時，空列表不當成空倉。公開持倉由獨立內置瀏覽器每60秒採集；不公開或已關閉的帳戶保留狀態，過期快照不作現倉。</p>'+rows+'</div>';}

document.addEventListener('click',event=>{const button=event.target.closest('[data-open-positions]');if(!button)return;document.querySelector('#reader').close();setView('overview');window.positionDesk.select(button.dataset.openPositions);document.querySelector('#position-desk').scrollIntoView({behavior:'smooth',block:'start'});});
setView('overview');
